import json, os, numpy as np
from PIL import Image
from rcb_client import Robot
r=Robot(); s=r.spec(); limits=np.array(s['qpos']['range']); lo=limits[:,0]; hi=limits[:,1]
def act(q): return np.clip(2*(np.array(q)-lo)/(hi-lo)-1,-1,1)
def observe(tag='obs'):
 o=r.observe(); save(o,tag);return o
def save(o,tag):
 for name,v in o.get('images',{}).items(): Image.fromarray(v).save('/app/output/'+tag+'_'+name+'.png')
 with open('/app/output/'+tag+'.json','w') as f: json.dump({k:v for k,v in o.items() if k not in ['images','depth']},f)
def move(q,n=1,tag=None):
 o=r.step('qpos',np.tile(act(q),(n,1)),images=bool(tag));
 if tag: save(o,tag)
 print('step',o['step'],'done',o['done'],'g',np.round(o['imu']['gravity'],3),'gyro',np.round(o['imu']['gyro'],3),'j',np.round(o['proprio']['joint_pos'][:10],2),flush=True)
 return o
def ramp(q,n=50,tag='ramp'):
 start=np.array(r.observe(False)['proprio']['joint_pos']); targets=[act(start+(np.array(q)-start)*i/n) for i in range(1,n+1)];o=r.step('qpos',targets);save(o,tag);print({k:v for k,v in o.items() if k not in ['images','depth']});return o
if __name__=='__main__':
 q=np.zeros(19);q[[1,6]]=-.12;q[[2,7]]=-1.35;q[[3,8]]=1.8;q[[4,9]]=-.45
 ramp(q,60,'sit1')
 move(q,60,'hold1')
